# Get all addresses we need to symbolicate
ADDRS="0x222098 0x2241ac 0x1abc80 0x16de04 0x2f4b20 0x2f4c84 0x2c1a40"
for addr in $ADDRS; do
  # Find the closest symbol below this address
  result=$(nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | awk -v target="$addr" '
